namespace ShareSync.Domain.Entities;

/// <summary>
/// FEATURE: Notification Center
/// DATABASE: Table — notifications
/// 
/// PURPOSE:
/// Stores in-app user notifications generated by alerts, dividend disbursements,
/// order confirmations, and system announcements. Powers unread counters and read-status tracking.
/// 
/// RELATIONAL MAPPING:
/// - Primary Key: NotificationId (AUTO_INCREMENT in MySQL)
/// - Foreign Key: UserId -> app_users(user_id) ON DELETE CASCADE
/// </summary>
public class Notification
{
    /// <summary>
    /// DATABASE: Primary key identifier.
    /// </summary>
    public int NotificationId { get; set; }

    /// <summary>
    /// Foreign key referencing the receiving user.
    /// SECURITY: Ownership Isolation guarantees users only see their own notifications.
    /// </summary>
    public int UserId { get; set; }

    /// <summary>
    /// Event category: 'ALERT', 'DIVIDEND', 'TRANSACTION', 'GOAL', 'SYSTEM'.
    /// </summary>
    public string NotificationType { get; set; } = string.Empty;

    /// <summary>
    /// Short notification summary headline.
    /// </summary>
    public string Title { get; set; } = string.Empty;

    /// <summary>
    /// Detailed notification body text.
    /// </summary>
    public string Message { get; set; } = string.Empty;

    /// <summary>
    /// Read state flag; false increments navbar unread badge.
    /// </summary>
    public bool IsRead { get; set; }

    /// <summary>
    /// Dispatch UTC timestamp.
    /// </summary>
    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

    /// <summary>
    /// Polymorphic reference to triggering entity type (e.g. "Alert", "Transaction").
    /// </summary>
    public string? RelatedEntityType { get; set; }

    /// <summary>
    /// ID of the triggering entity.
    /// </summary>
    public int? RelatedEntityId { get; set; }

    /// <summary>
    /// Navigation property to parent user.
    /// </summary>
    public AppUser? User { get; set; }
}

